package com.project.system.service;
import java.util.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service public class MerchantService {
 @Autowired private JdbcTemplate db;
 private final String select="select m.id,concat('SH',lpad(cast(m.id as char),8,'0')) merchant_no,m.name,m.active,p.category,p.contact_name,p.phone,p.address,p.remark,p.created_at,p.updated_at,ac.public_id api_id,e.owner_name,e.owner_phone,e.license_no,e.permit_no,e.permit_expiry,e.introduction,e.license_image,e.permit_image,e.merchant_image from campus_merchant m left join campus_merchant_profile p on m.id=p.merchant_id left join campus_merchant_extra e on e.merchant_id=m.id left join campus_api_credential ac on ac.merchant_id=m.id";
 public Map<String,Object> info(long id){List<Map<String,Object>> rows=db.queryForList(select+" where m.id=?",id);if(rows.isEmpty())throw new IllegalArgumentException("商户不存在");return rows.get(0);}
 public Map<String,Object> search(String name,String number,String category,Integer active,int page){return search(name,number,category,active,page,null,null,null);}
 public Map<String,Object> search(String name,String number,String category,Integer active,int page,String owner,String start,String end){String where=" where 1=1";List<Object> a=new ArrayList<>();if(name!=null&&!name.trim().isEmpty()){where+=" and m.name like ?";a.add("%"+name.trim()+"%");}if(number!=null&&!number.trim().isEmpty()){where+=" and concat('SH',lpad(cast(m.id as char),8,'0'))=?";a.add(number.trim());}if(category!=null&&!category.isEmpty()){where+=" and p.category=?";a.add(category);}if(active!=null){where+=" and m.active=?";a.add(active);}if(owner!=null&&!owner.trim().isEmpty()){where+=" and exists(select 1 from campus_merchant_extra ex where ex.merchant_id=m.id and ex.owner_name like ?)";a.add("%"+owner.trim()+"%");}for(String date:Arrays.asList(start,end))if(date!=null&&!date.isEmpty()){try{java.time.LocalDate.parse(date);}catch(Exception ex){throw new IllegalArgumentException("创建日期格式无效");}}if(start!=null&&!start.isEmpty()){where+=" and p.created_at>=?";a.add(start);}if(end!=null&&!end.isEmpty()){where+=" and p.created_at<date_add(?,interval 1 day)";a.add(end);}
 Map<String,Object> out=new LinkedHashMap<>();out.put("total",db.queryForObject("select count(*) from campus_merchant m left join campus_merchant_profile p on m.id=p.merchant_id"+where,Long.class,a.toArray()));a.add(20);a.add((Math.max(1,Math.min(page,100000))-1)*20);out.put("rows",db.queryForList(select+where+" order by m.id desc limit ? offset ?",a.toArray()));return out;}
 private String text(String v,int max,String label,boolean required){String s=v==null?"":v.trim();if((required&&s.isEmpty())||s.length()>max)throw new IllegalArgumentException(label+"不能为空或长度超限");return s;}
 @Transactional public long save(Long id,String name,String category,String contact,String phone,String address,String remark,long actor){name=text(name,100,"商户名称",true);contact=text(contact,50,"联系人",true);phone=text(phone,30,"联系电话",true);address=text(address,200,"经营地址",true);remark=text(remark,500,"备注",false);if(!phone.matches("[0-9+() -]{5,30}"))throw new IllegalArgumentException("联系电话格式无效");if(category==null||"SYSTEM".equals(category)||db.queryForObject("select count(*) from campus_merchant_category where code=?",Integer.class,category)==0)throw new IllegalArgumentException("商户类型无效");
 String before="";boolean create=id==null;if(create){db.queryForObject("select seq from campus_merchant_sequence where id=1 for update",Long.class);long next=db.queryForObject("select greatest((select seq from campus_merchant_sequence where id=1),coalesce(max(id),0))+1 from campus_merchant",Long.class);db.update("update campus_merchant_sequence set seq=? where id=1",next);id=next;db.update("insert into campus_merchant(id,name,active) values(?,?,1)",id,name);}else{if(id==3)throw new IllegalArgumentException("系统模拟划扣商户不可修改");if(db.queryForList("select id from campus_merchant where id=? for update",id).isEmpty())throw new IllegalArgumentException("商户不存在");before=info(id).toString();db.update("update campus_merchant set name=? where id=?",name,id);}
 db.update("insert into campus_merchant_profile(merchant_id,category,contact_name,phone,address,remark) values(?,?,?,?,?,?) on duplicate key update category=values(category),contact_name=values(contact_name),phone=values(phone),address=values(address),remark=values(remark)",id,category,contact,phone,address,remark);
 db.update("insert into campus_merchant_audit(merchant_id,action,detail,actor_id) values(?,?,?,?)",id,create?"CREATE":"UPDATE",create?"创建商户 "+name:"修改前："+before+"；修改后："+info(id),actor);if(id!=3)db.update("insert ignore into campus_api_credential(merchant_id,public_id,secret) values(?,?,?)",id,UUID.randomUUID().toString(),ApiSecurity.secret());return id;}
 @Transactional public void status(long id,int active,String reason,long actor){if(id==3)throw new IllegalArgumentException("系统模拟划扣商户不可停用或修改");if(active!=0&&active!=1)throw new IllegalArgumentException("状态无效");reason=text(reason,200,"操作原因",true);if(db.queryForList("select id from campus_merchant where id=? for update",id).isEmpty())throw new IllegalArgumentException("商户不存在");db.update("update campus_merchant set active=? where id=?",active,id);db.update("insert into campus_merchant_audit(merchant_id,action,detail,actor_id) values(?,?,?,?)",id,active==1?"ENABLE":"DISABLE",reason,actor);}
 public Map<String,Object> detail(long id,int page){Map<String,Object> out=new LinkedHashMap<>();out.put("merchant",info(id));String from=" from campus_ledger l left join campus_ledger original on l.original_id=original.id where l.merchant_id=? or (l.kind='REFUND' and original.merchant_id=?)";out.put("total",db.queryForObject("select count(*)"+from,Long.class,id,id));out.put("summary",db.queryForMap("select coalesce(sum(case when l.kind='PAY' then l.amount else 0 end),0) consumption,coalesce(sum(case when l.kind='REFUND' then l.amount else 0 end),0) refunds"+from,id,id));out.put("rows",db.queryForList("select l.transaction_no,l.kind,l.amount,l.created_at,l.merchant_name_snapshot,original.transaction_no original_no,(select o.order_no from campus_recharge_order o where o.ledger_id=l.id) order_no"+from+" order by l.id desc limit 20 offset ?",id,id,(Math.max(1,Math.min(page,100000))-1)*20));out.put("audit",db.queryForList("select action,detail,actor_id,created_at from campus_merchant_audit where merchant_id=? order by id desc limit 50",id));return out;}

 public List<Map<String,Object>> categories(){return db.queryForList("select code,name from campus_merchant_category order by created_at,code");}
 @Transactional public String addCategory(String name,long actor){name=text(name,40,"类型名称",true);if(db.queryForObject("select count(*) from campus_merchant_category where name=?",Integer.class,name)>0)throw new IllegalArgumentException("类型名称已存在");String code="T"+UUID.randomUUID().toString().replace("-","").substring(0,16);db.update("insert into campus_merchant_category(code,name) values(?,?)",code,name);return code;}
 @Transactional public long saveFull(Long id,String name,String category,String contact,String phone,String address,String remark,long actor,Map<String,String> x){
 String owner=text(x.get("owner_name"),50,"负责人",true),ownerPhone=text(x.get("owner_phone"),30,"负责人电话",true);if(!ownerPhone.matches("[0-9+() -]{5,30}"))throw new IllegalArgumentException("负责人电话格式无效");
 String license=text(x.get("license_no"),100,"营业执照编号",false),permit=text(x.get("permit_no"),100,"许可编号",false),intro=text(x.get("introduction"),2000,"商户简介",false),expiry=x.get("permit_expiry");if(expiry!=null&&!expiry.isEmpty())try{java.time.LocalDate.parse(expiry);}catch(Exception e){throw new IllegalArgumentException("许可有效期无效");}
 for(String key:Arrays.asList("license_image","permit_image","merchant_image")){String v=x.get(key);if(v!=null&&!v.isEmpty()&&db.queryForObject("select count(*) from campus_merchant_image where id=?",Integer.class,v)==0)throw new IllegalArgumentException("图片不存在，请重新上传");}
 long merchant=save(id,name,category,contact,phone,address,remark,actor);String before=db.queryForList("select * from campus_merchant_extra where merchant_id=?",merchant).toString();
 db.update("insert into campus_merchant_extra(merchant_id,owner_name,owner_phone,license_no,permit_no,permit_expiry,introduction,license_image,permit_image,merchant_image) values(?,?,?,?,?,?,?,?,?,?) on duplicate key update owner_name=values(owner_name),owner_phone=values(owner_phone),license_no=values(license_no),permit_no=values(permit_no),permit_expiry=values(permit_expiry),introduction=values(introduction),license_image=values(license_image),permit_image=values(permit_image),merchant_image=values(merchant_image)",merchant,owner,ownerPhone,license,permit,expiry==null||expiry.isEmpty()?null:expiry,intro,empty(x.get("license_image")),empty(x.get("permit_image")),empty(x.get("merchant_image")));
 db.update("insert into campus_merchant_audit(merchant_id,action,detail,actor_id) values(?,'UPDATE',?,?)",merchant,"扩展资料修改前："+before+"；修改后："+db.queryForList("select * from campus_merchant_extra where merchant_id=?",merchant),actor);return merchant;}
 private String empty(String v){return v==null||v.isEmpty()?null:v;}
 public String image(byte[] bytes,long actor){if(bytes.length==0||bytes.length>3*1024*1024)throw new IllegalArgumentException("图片大小须为1字节至3MB");try{javax.imageio.stream.ImageInputStream input=javax.imageio.ImageIO.createImageInputStream(new java.io.ByteArrayInputStream(bytes));try{java.util.Iterator<javax.imageio.ImageReader> readers=javax.imageio.ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IllegalArgumentException("仅支持有效PNG或JPEG图片");javax.imageio.ImageReader reader=readers.next();try{reader.setInput(input);String format=reader.getFormatName();if(!format.equalsIgnoreCase("PNG")&&!format.equalsIgnoreCase("JPEG"))throw new IllegalArgumentException("仅支持PNG或JPEG图片");if((long)reader.getWidth(0)*reader.getHeight(0)>12000000)throw new IllegalArgumentException("图片像素不能超过1200万");java.awt.image.BufferedImage image=reader.read(0);java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,format.equalsIgnoreCase("PNG")?"png":"jpg",output);byte[] clean=output.toByteArray();if(clean.length>8*1024*1024)throw new IllegalArgumentException("图片解码后过大，请压缩后上传");String key=UUID.randomUUID().toString();db.update("insert into campus_merchant_image(id,mime,content,actor_id) values(?,?,?,?)",key,format.equalsIgnoreCase("PNG")?"image/png":"image/jpeg",clean,actor);return key;}finally{reader.dispose();}}finally{input.close();}}catch(java.io.IOException e){throw new IllegalArgumentException("图片损坏或格式不支持");}}
 public Map<String,Object> image(String id){List<Map<String,Object>> rows=db.queryForList("select mime,content from campus_merchant_image where id=?",id);if(rows.isEmpty())throw new IllegalArgumentException("图片不存在");return rows.get(0);}
}
